{
  "implementation": "def solve(case):
    edges = case["edges"]
    refinement = case["refinement"]
    members = {}
    for node, comm in refinement.items():
        members.setdefault(comm, []).append(node)
    for comm in members:
        members[comm].sort()
    agg_edges = {}
    for u, v, w in edges:
        cu = refinement[u]
        cv = refinement[v]
        pair = tuple(sorted([cu, cv]))
        agg_edges[pair] = agg_edges.get(pair, 0) + w
    aggregate_edges = sorted([[c1, c2, w] for (c1, c2), w in agg_edges.items()])
    return {"aggregate_edges": aggregate_edges, "members": members}"
}
